/** One recorded lifecycle moment: a backup moved from one state to
 *  another. This is a read of the durable, append-only transition
 *  record, not a second event stream. */
export interface WireActivityEvent {
  artifact_id: string;
  artifact_name: string;
  backup_set_id: string;
  detail?: string;
  from?: string;
  occurred_at: string;
  set_name: string;
  source_name: string;
  to: string;
}

/** POST /backup-sets/{source}/{set}/retention/apply. */
export interface WireApplyRetentionRequest {
  plan_id: string;
}

/** One backup this deployment holds, as the API reports it. Nothing
 *  here names an implementation: the fields describe a backup's
 *  identity, freshness and trustworthiness, never how it is stored. */
export interface WireArtifact {
  backup_set_id: string;
  checksum?: string;
  checksum_algorithm?: string;
  discovered_at: string;
  id: string;
  local_path: string;
  name: string;
  placements: WirePlacement[];
  quarantine_irrecoverable: boolean;
  quarantine_reason?: string;
  quarantined: boolean;
  remote_path: string;
  remote_source_removed_at?: string;
  retention_policy: "configured" | "none";
  retention_tier?: string;
  set_name: string;
  size_bytes: number;
  source_name: string;
  state: string;
  updated_at: string;
  validation: "passed" | "failed" | "pending";
  validation_detail?: string;
}

/** The verdict of re-checking one quarantined backup. Nothing is
 *  written and the backup is not moved: a pass is evidence for an
 *  operator deciding whether to retry, not a rehabilitation. */
export interface WireArtifactCheckResponse {
  checked: boolean;
  passed: boolean;
  reason?: string;
}

/** POST /quarantine/{source}/{set}/{name}/reinstate. Re-checks one
 *  quarantined backup's durable local copy and, when what it finds is
 *  enough, returns it to the state it already held so it counts as a
 *  restore point again. `reinstated` and `passed` are separate:
 *  `passed` is the verdict of the checks, `reinstated` is whether the
 *  backup actually moved. A backup reinstated this way NEVER
 *  authorises deleting its remote source again; that forfeiture is
 *  permanent and is what makes the action safe to offer. */
export interface WireArtifactReinstateResponse {
  checked: boolean;
  passed: boolean;
  reason?: string;
  reinstated: boolean;
  state?: string;
}

/** The FLAT error body the /auth operations return, with the
 *  correlation id in the body as well as the header. Deliberately
 *  recorded as a second shape rather than pretended away:
 *  apps/common/auth/local diverged from the envelope above before
 *  this contract existed. */
export interface WireAuthErrorResponse {
  code: ApiErrorCode;
  correlationId: string;
  message: string;
}

/** A persisted backup set as the API reports it. */
export interface WireBackupSet {
  completion_strategy: "rename" | "marker" | "stable";
  disabled: boolean;
  host: string;
  id: string;
  include: string[];
  local_path: string;
  name: string;
  port: number;
  read_only: boolean;
  remote_path: string;
  retention_is_override: boolean;
  source_name: string;
  ssh_key_id: string;
  stable_for_seconds: number;
  stale_after_seconds: number;
  trusted_host_key_recorded_at?: string;
  trusted_host_keys?: WireTrustedHostKey[];
  user: string;
  validator_id: string;
}

/** POST /backup-sets/{source}/{set}/edit-hold. The lease just taken
 *  or renewed, plus what taking it interrupted. `stopped` is null
 *  when nothing was running, so a client never claims to have stopped
 *  something it did not. */
export interface WireBackupSetEditHold {
  backup_set_id: string;
  expires_at: string;
  stopped?: WireRunningWork;
}

/** GET /backup-sets/{source}/{set}/edit-hold. What entering edit mode
 *  for this backup set would interrupt, and whether a hold is already
 *  in force. `running` is null when no cycle is currently inside this
 *  set, which is what lets a client open edit mode with no prompt for
 *  a risk that does not exist. */
export interface WireBackupSetEditHoldState {
  backup_set_id: string;
  expires_at?: string;
  held: boolean;
  running?: WireRunningWork;
}

/** One backup set's health verdict: whether its backups are fresh and
 *  trustworthy, and whether they are on the storage medium its
 *  retention policy says they belong on. This is the backup half of
 *  health, and it deliberately carries no process or build fact: a
 *  running service is not evidence that backups are landing. The
 *  placement figures come from durable state rather than from the
 *  last pass, so a deployment nobody has run a cycle in front of
 *  still reports relocations that have been failing for weeks. */
export interface WireBackupSetHealth {
  away_from_home: number;
  away_from_home_oldest_age_seconds?: number;
  backup_set_id: string;
  current_transfers: number;
  failed_move_oldest_age_seconds?: number;
  failed_move_reason?: string;
  failed_moves: number;
  failures: number;
  free_bytes?: number;
  free_bytes_known: boolean;
  halt_reason?: "HOST_KEY_CHANGED" | "AUTHENTICATION_FAILED" | "KEY_PERMISSIONS";
  last_completed_backup_at?: string;
  newest_good_backup_at?: string;
  open_move_oldest_age_seconds?: number;
  open_moves: number;
  pending_deletes: number;
  quarantined_count: number;
  quarantined_lost_count: number;
  read_only_retained_count: number;
  reason: string;
  reinstated_remote_retained_count: number;
  set_name: string;
  source_name: string;
  stale_after_seconds: number;
  state: "HEALTHY" | "DEGRADED" | "STALE" | "FAILING";
  storage_level?: "OK" | "WARNING" | "CRITICAL";
  total_bytes?: number;
  unconfirmed_location: number;
}

/** Which retention policy one backup set is retained under, and where
 *  that policy came from. All of it is served together because 'what
 *  is deciding' and 'is that this set's own or the deployment's' are
 *  one question for an operator reading a preview that is about to
 *  delete something, and answering it in two calls is how a surface
 *  shows a chain beside the wrong attribution. */
export interface WireBackupSetRetention {
  backup_set_id: string;
  deployment: WireRetentionSettings;
  effective: WireRetentionSettings;
  is_override: boolean;
  override?: WireRetentionOverride;
}

/** Everything it takes to DESCRIBE one backup set: where it reads
 *  from, where it writes to, how it decides a file is complete, and
 *  whether it starts enabled. ssh_key_id and known_hosts_line carry
 *  REFERENCES produced by /ssh-keys and /ssh/host-key-probe, never
 *  key material. Nothing here asks for anything to be RUN, which is
 *  what makes it the body of two different operations: POST
 *  /backup-sets folds a set into a configuration that already exists,
 *  and POST /system/first-run writes the first configuration there
 *  has ever been. Those two share this base rather than restating it,
 *  so the wizard that collects these answers can never be right about
 *  one operation and wrong about the other. */
export interface WireBackupSetSpec {
  completion_strategy: "rename" | "marker" | "stable";
  disabled?: boolean;
  host: string;
  include?: string[];
  known_hosts_line: string;
  local_path: string;
  name: string;
  port: number;
  read_only?: boolean;
  remote_path: string;
  source_name?: string;
  ssh_key_id: string;
  stable_for_seconds?: number;
  stale_after_seconds?: number;
  user: string;
  validator_id?: string;
}

/** GET /system/capabilities. The API expression of the
 *  PlatformCapabilities contract (apps/common/platform/capabilities).
 *  A capability says what a platform CAN do; it never says who MAY do
 *  it, and server-side authorization never consults it. */
export interface WireCapabilitiesResponse {
  app_store_packaging: boolean;
  embedded_window: boolean;
  native_auth: boolean;
  native_notifications: boolean;
  platform: "generic" | "ugos" | "synology" | "truenas" | "unraid" | "openmediavault" | "proxmox";
  storage_picker: boolean;
}

/** FR-21's capacity configuration as it is actually deciding. Every
 *  number is BYTES: the MB/GB picker beside the field is display only
 *  and converts at the edge, so nothing on this boundary carries a
 *  unit. */
export interface WireCapacitySettings {
  backup_root: string;
  backup_root_configured: boolean;
  cap_bytes: number;
  critical_free_bytes: number;
  safety_margin_bytes: number;
  warning_free_bytes: number;
}

/** One recovery manifest a catalog pass could not use. */
export interface WireCatalogFailure {
  backup_set_id: string;
  path?: string;
  reason: string;
}

/** POST /catalog/scan and POST /catalog/rebuild. Both return this
 *  shape, because a scan is the rebuild with nothing written: a
 *  preview computed by a second implementation would be a preview of
 *  something else. */
export interface WireCatalogReportResponse {
  already_present: number;
  dry_run: boolean;
  failures: WireCatalogFailure[];
  reconstructed: number;
  scanned: number;
}

/** POST /system/first-run. The backup set the first configuration was
 *  written around, NESTED rather than flattened, which is the one
 *  place this contract deliberately differs from
 *  CreateBackupSetResponse beside it. What this operation creates is
 *  a whole configuration; the set is its first member, and
 *  restart_required is a fact about the instance, not about the set.
 *  Keeping backup_set as exactly a BackupSet means a later v1
 *  addition describing the configuration lands beside it instead of
 *  becoming indistinguishable from a backup-set field, and can never
 *  collide with a field BackupSet itself grows. */
export interface WireCompleteFirstRunResponse {
  backup_set: WireBackupSet;
  restart_required: boolean;
}

/** The CONFIG_REVISION_STALE 409 body. It carries the current
 *  revision as a structured field so a client retries against a value
 *  it can rely on rather than one parsed out of prose. */
export interface WireConfigRevisionStaleResponse {
  config_revision: string;
  error: WireErrorBody;
}

/** One step of a connection test. `outcome` is passed, failed or
 *  skipped, and skipped is a first-class answer rather than a quiet
 *  pass: a surface that renders a skipped authentication as anything
 *  but "this was never tried" has told an operator their credentials
 *  are fine on the strength of a step that never ran. `category` is
 *  the machine-readable half a surface branches on; `detail` is a
 *  sentence the engine composed and never an underlying transport
 *  error's text. This is MediumPreflightCheck's shape asked about a
 *  SOURCE instead of a destination, deliberately, so a preflight
 *  table and a connection-test table are two renderings of one idea
 *  rather than two contracts. */
export interface WireConnectionCheck {
  category?: string;
  detail: string;
  duration_ms?: number;
  outcome: "passed" | "failed" | "skipped";
  step: "credentials" | "resolve" | "connect" | "host_key" | "authenticate" | "list";
}

/** POST /backup-sets. The backup-set spec, plus the two things only a
 *  create can ask for: that the new set also runs at once, and that
 *  it may take over history already on its id. */
export interface WireCreateBackupSetRequest extends WireBackupSetSpec {
  acknowledge_repoint?: boolean;
  run_immediately?: boolean;
}

/** POST /backup-sets. The created set, plus at most one of operation
 *  (the run_immediately branch started) or run_error (it did not).
 *  Always 201: the set itself exists either way. */
export interface WireCreateBackupSetResponse extends WireBackupSet {
  operation?: WireOperation;
  run_error?: string;
}

/** POST /auth/login and POST /auth/enroll. camelCase, unlike every
 *  schema above: apps/common/auth/local predates the snake_case
 *  convention the rest of /api/v1 uses. Recorded here as it is rather
 *  than silently normalised; see docs/api/contract.md for why fixing
 *  it is a separate issue. */
export interface WireCredentialsRequest {
  password: string;
  username: string;
}

/** What a finished cycle's move pass got done: how many artifacts
 *  were due to move to the medium their retention tier names, and how
 *  many arrived. Without these, a cycle in which every move was
 *  refused is indistinguishable from one in which every move landed,
 *  which is the same defect artifacts_walked and artifacts_through
 *  exist to remove one layer down. There is no reason string here,
 *  deliberately: the engine's own refusal sentence is built from
 *  whatever the transport handed back, about an endpoint, a bucket
 *  and a credential reference, so it stays on the terminal and in the
 *  event stream and never on this boundary. */
export interface WireCycleMoveOutcome {
  attempted: number;
  landed: number;
}

/** What a finished run cycle actually got done, read off the
 *  operation's own recorded summary. A cycle "completed" when it ran
 *  to the end, which is a narrower statement than anyone reading it
 *  assumes: an artifact's own quarantine is a business outcome and
 *  not an operation failure, so a cycle that backed nothing up
 *  finishes looking exactly like one that backed everything up. These
 *  counts are what tell the two apart. */
export interface WireCycleOutcome {
  artifacts_through: number;
  artifacts_walked: number;
  backup_sets_processed: number;
  moves?: WireCycleMoveOutcome;
}

/** The nested error body every operation outside /auth returns. code
 *  is stable and machine-readable; message is human-readable and MAY
 *  change without notice. */
export interface WireErrorBody {
  code: ApiErrorCode;
  message: string;
}

/** The error envelope every operation outside /auth returns. The
 *  correlation id travels in the X-Correlation-Id response header. */
export interface WireErrorResponse {
  error: WireErrorBody;
}

/** GET /system/first-run. The one question a client asks before it
 *  decides whether to render the setup flow or the application.
 *  Deliberately one field: a client that has just been handed a 503
 *  NOT_CONFIGURED needs to know which screen to show, not why. */
export interface WireFirstRunStatusResponse {
  configured: boolean;
}

/** GET /system/health. Every configured backup set's freshness
 *  verdict, computed fresh on every call. Build and process facts are
 *  GET /system/version's, deliberately not restated here. */
export interface WireHealthResponse {
  backup_sets: WireBackupSetHealth[];
  generated_at: string;
}

/** POST /ssh/host-key-probe. Opens a real outbound connection, trusts
 *  nothing. */
export interface WireHostKeyProbeRequest {
  host: string;
  port: number;
}

/** What the server actually saw. Presenting it to an operator for
 *  approval is the caller's job. */
export interface WireHostKeyProbeResponse {
  algorithm: string;
  fingerprint: string;
  known_hosts_line: string;
}

/** POST /ssh-keys/from-candidate. Selecting a key this host already
 *  found is a different act from pasting one this host has never
 *  seen, and it carries a different body: an opaque handle and no key
 *  material at all. It is a separate operation rather than a second
 *  mode of POST /ssh-keys because a shared body with two optional
 *  halves would have had to stop requiring private_key_pem, and this
 *  contract does not withdraw a requirement it has already made. */
export interface WireImportSSHKeyFromCandidateRequest {
  candidate_id: string;
}

/** POST /ssh-keys. Sent once; the caller discards its own copy
 *  immediately. Pasted material only: selecting a key this host
 *  already holds is POST /ssh-keys/from-candidate, which takes a
 *  handle instead. */
export interface WireImportSSHKeyRequest {
  passphrase?: string;
  private_key_pem: string;
}

/** The reference a later create-backup-set call carries instead of
 *  key material. */
export interface WireImportSSHKeyResponse {
  algorithm: string;
  fingerprint: string;
  id: string;
}

/** POST /storage-credentials. Sent once; the caller discards its own
 *  copy the moment an id comes back. This is the ONLY place in this
 *  contract where S3 credential material appears, in either
 *  direction, and it is write-only: no operation anywhere echoes it,
 *  returns it or derives anything displayable from it. */
export interface WireImportStorageCredentialsRequest {
  access_key_id: string;
  secret_access_key: string;
  session_token?: string;
}

/** The reference an import returns, and nothing else. There is
 *  deliberately no fingerprint, no masked key and no last-four here,
 *  unlike ImportSSHKeyResponse's algorithm and fingerprint: an SSH
 *  public key's fingerprint is a safe thing to show a person, and
 *  nothing derived from an S3 credential is. */
export interface WireImportStorageCredentialsResponse {
  id: string;
}

/** GET /activity, newest first. */
export interface WireListActivityResponse {
  events: WireActivityEvent[];
}

/** GET /backups and GET /quarantine. An object with one array field,
 *  never a bare top-level array. */
export interface WireListArtifactsResponse {
  artifacts: WireArtifact[];
}

/** GET /backup-sets. An object with one array field, never a bare
 *  top-level array. */
export interface WireListBackupSetsResponse {
  backup_sets: WireBackupSet[];
}

/** GET /operations, newest first. The list counterpart of GET
 *  /operations/{id}, for a client that has no operation id to poll
 *  with. */
export interface WireListOperationsResponse {
  operations: WireOperation[];
}

/** GET /ssh/key-candidates. The locations travel beside the
 *  candidates, in one response, so a client cannot render one without
 *  the other. */
export interface WireListSSHKeyCandidatesResponse {
  candidates: WireSSHKeyCandidate[];
  locations: WireSSHKeyDiscoveryLocation[];
}

/** GET /ssh-keys. The read this API never had: an imported key's id
 *  used to cross the wire exactly once, in the response to the POST
 *  that created it, so ssh_key_id took a value nothing in the product
 *  would tell anybody. */
export interface WireListSSHKeysResponse {
  keys: WireSSHKey[];
}

/** Every declared storage destination, in declaration order. An
 *  object rather than a bare array, matching every other list in this
 *  contract: a top-level array has nowhere to grow a field, and the
 *  day this needs a count or a cursor it would be a breaking change. */
export interface WireListStorageMediumsResponse {
  mediums: WireStorageMediumSummary[];
}

/** GET /system/storage. The manager-wide reading a dashboard gauge is
 *  drawn from, plus one entry per configured backup set. */
export interface WireListStorageStatusResponse {
  backup_sets: WireStorageStatus[];
  manager: WireManagerStorage;
}

/** GET /validators. Read-only by design: a client-extensible catalog
 *  would be an arbitrary-command surface. */
export interface WireListValidatorsResponse {
  validators: WireValidator[];
}

/** The log that belongs to no single backup set, served in its own
 *  right rather than copied onto every set's feed. A cycle starting
 *  covers every set and a capacity check is about a filesystem, so
 *  neither belongs on one set's strip; until this bucket existed the
 *  only alternatives were dropping those lines (which hides them) or
 *  reporting them on every strip, and the second is what shipped, so
 *  on a real deployment every set's strip showed the same log and the
 *  shared lines crowded out each set's own. It is absent when the
 *  caller narrowed the reading to one backup set, because a caller
 *  that named a set asked about that set. It is present, and is the
 *  whole answer, for a deployment with no configured backup sets at
 *  all, which is exactly when a new operator is pressing buttons in a
 *  wizard and has nothing else to read. */
export interface WireLiveActivityDeployment {
  dropped: boolean;
  events: WireLiveActivityEvent[];
  latest_sequence: number;
  oldest_sequence: number;
  truncated: boolean;
}

/** One line of the live feed. It carries the engine's own event name,
 *  the engine's own severity and the event's own fields, because what
 *  a moment is worth calling is presentation and belongs to whichever
 *  client is presenting: a severity invented on the way to the wire
 *  would freeze one screen's display decision for every other client.
 *  The level is not such a decision, it is what the emitter chose
 *  when it decided a line was a warning rather than a note, so it is
 *  carried through rather than re-derived. */
export interface WireLiveActivityEvent {
  at: string;
  event: string;
  fields: WireLiveActivityField[];
  level: "debug" | "info" | "warn" | "error";
  message: string;
  scope: "deployment" | "set";
  sequence: number;
}

/** One field of an event, rendered as a string and already redacted.
 *  A pair rather than a map because the order the event logged its
 *  fields in is the order that reads best, and because a client
 *  rendering a line wants them in that order without sorting. */
export interface WireLiveActivityField {
  key: string;
  value: string;
}

/** One reading of the live feed. It is a snapshot a client polls, not
 *  a stream: this product runs on a NAS behind whatever reverse proxy
 *  the operator already had, and behind the UI container's own proxy
 *  in the two-container topology, so a held-open response is at the
 *  mercy of every buffering and idle-timeout default in that path. A
 *  plain GET works through all of them, needs no reconnection logic,
 *  and is exactly as readable from a terminal as from a browser. The
 *  cursor on the request is what keeps polling cheap. */
export interface WireLiveActivityResponse {
  deployment?: WireLiveActivityDeployment;
  epoch: string;
  observed_at: string;
  poll_after_ms: number;
  sets: WireLiveActivitySet[];
}

/** What one backup set is doing right now, and the tail of events
 *  behind it. Every configured set appears whether or not anything
 *  has happened to it: a panel that shows up only during activity
 *  teaches an operator to hunt for it, and its absence then means
 *  either nothing is running or nothing is reporting, with no way to
 *  tell which. */
export interface WireLiveActivitySet {
  active: boolean;
  artifact?: string;
  artifacts_completed: number;
  artifacts_total?: number;
  backup_set_id: string;
  bytes_per_second?: number;
  bytes_total?: number;
  bytes_transferred?: number;
  dropped: boolean;
  events: WireLiveActivityEvent[];
  failures: number;
  finished_at?: string;
  latest_sequence: number;
  oldest_sequence: number;
  outcome?: "ok" | "failed" | "stopped";
  progress_basis: "artifacts" | "unknown";
  stage?: "discovering" | "transferring" | "verifying" | "committing" | "cleaning-remote";
  started_at?: string;
  truncated: boolean;
}

/** The one manager-wide storage reading: what the backup root's
 *  filesystem holds, what this manager itself accounts for, and which
 *  of the two the gauge is a fraction of. Distinct from the
 *  per-backup-set list beside it, which answers a different question
 *  and cannot answer this one: a fresh instance has no backup sets,
 *  two sets on one volume are two entries reporting the same disk,
 *  and the storage cap is one ceiling for the whole manager. When
 *  known is false every byte count is 0 and level is empty; render
 *  that as "capacity is not known yet", never as zero bytes and never
 *  as a percentage. */
export interface WireManagerStorage {
  available_bytes: number;
  binding_constraint: "" | "disk" | "cap";
  cap_bytes: number;
  catalog_bytes: number;
  catalog_bytes_known: boolean;
  critical_free_bytes: number;
  denominator: "disk" | "cap";
  free_bytes: number;
  headroom_bytes: number;
  known: boolean;
  level: "" | "OK" | "WARNING" | "CRITICAL";
  limit_bytes: number;
  measured_path: string;
  other_bytes: number;
  other_bytes_known: boolean;
  total_bytes: number;
  unknown_reason: "" | "no_backup_root" | "not_created" | "unreadable" | "misconfigured";
  used_bytes: number;
  warning_free_bytes: number;
}

/** One step of a storage-medium preflight. There is deliberately no
 *  field here for key material of any kind, and there never will be
 *  (FR-33): `detail` is one of the engine's own sentences, never the
 *  text of what actually came back, because that names a path on the
 *  host or the name of an environment variable. The classified cause
 *  goes to this manager's log instead. */
export interface WireMediumPreflightCheck {
  category?: string;
  detail: string;
  outcome: "passed" | "failed" | "skipped";
  step: "credentials" | "reach" | "deliverable" | "write" | "read_back" | "storage_class" | "verification" | "delete";
}

/** The result of proving one storage medium works. The preflight
 *  writes a small probe object to the medium, reads it back byte for
 *  byte, checks the storage class it landed in against the one the
 *  configuration claims, asks whether the verification class the
 *  medium declares can actually be achieved there, and deletes the
 *  probe. That is deliberately more than a reachability ping: a wrong
 *  region, a policy that denies PutObject and an endpoint that
 *  silently ignores storage_class all answer a ping perfectly well
 *  and then fail a move, in the middle of a cycle, after an artifact
 *  has already been chosen to leave local disk. A medium that does
 *  not work is a 200 with `ok` false, not an error: a bucket that is
 *  not there is what an operator did, not what broke, exactly as a
 *  failed backup-set connection test reports itself. The operation
 *  takes an id and never a candidate medium, unlike that connection
 *  test: a medium is declared in the configuration file and nowhere
 *  else, and the only fields that would make a candidate one
 *  meaningful are the three credential references, so a request body
 *  for one would make a path on this host into something an API
 *  caller sends (FR-33). Nothing schedules this; it is a real side
 *  effect on somebody's bucket and it runs only because a person
 *  asked. */
export interface WireMediumPreflightResponse {
  checks: WireMediumPreflightCheck[];
  medium: string;
  ok: boolean;
}

/** One durable operation record. Timestamp fields are omitted, not
 *  zero-valued, until the event they name has happened. progress is
 *  the separate, ephemeral thing: see OperationProgress for why it is
 *  a nested object that is simply absent rather than a set of fields
 *  on this record. */
export interface WireOperation {
  action?: string;
  actor?: string;
  backup_set_id?: string;
  config_revision?: string;
  created_at?: string;
  cycle?: WireCycleOutcome;
  error?: string;
  finished_at?: string;
  operation_id: string;
  progress?: WireOperationProgress;
  restore?: WireOperationRestore;
  result?: string;
  started_at?: string;
  status: string;
}

/** Live progress for an operation that is running in THIS process
 *  right now (docs/EPIC-B-multi-nas.md §52). It is sampled from the
 *  transfer engine while a run cycle executes and is never written to
 *  the operations table: an operation record is durable and
 *  crash-safe, and progress is neither, so persisting it would put a
 *  tick-rate write path on the one record whose durability guarantees
 *  exist to avoid exactly that, and would resurrect a dead cycle's
 *  last reading after a restart as though it were live. So this field
 *  is present only while the cycle producing it is executing here. A
 *  finished operation, and one that was running before a restart,
 *  both carry no progress object at all, which is not the same answer
 *  as zero and must not be rendered as one. Nothing here is a
 *  percentage of the whole operation: a run cycle is a pass over
 *  every enabled backup set, and the artifacts it will find are not
 *  known when it starts, so no honest denominator for the whole
 *  exists. The byte counters describe the ONE artifact being copied
 *  at observed_at; the counters beside them say where in the cycle
 *  that artifact sits. */
export interface WireOperationProgress {
  artifact?: string;
  artifacts_done: number;
  backup_set_id?: string;
  backup_sets_done: number;
  backup_sets_total: number;
  bytes_per_second?: number;
  bytes_total?: number;
  bytes_transferred?: number;
  observed_at: string;
  sequence: number;
  stage: "discovering" | "transferring" | "verifying" | "committing" | "cleaning-remote";
}

/** A restore operation's own facts: what was asked for, which never
 *  changes, and where it has actually got to, which is re-derived
 *  from the storage provider on every read rather than remembered.
 *  Absent on every other action. There is no percentage field, no
 *  completion-time field and no cost field: S3 reports a restore as
 *  running or finished and nothing else, and this product holds no
 *  price list, so any of the three would be invented. */
export interface WireOperationRestore {
  access?: string;
  artifact_id?: string;
  billing?: string;
  detail?: string;
  medium?: string;
  restored_until?: string;
  storage_class?: string;
  wait?: string;
  window_days?: number;
}

/** One DURABLE copy of one backup, and where it actually is (EPIC E,
 *  FR-29). A placement exists because the journal recorded a finished
 *  copy, so the ABSENCE of a placement is the absence of a copy: a
 *  transfer still in flight has no placement at all, and neither does
 *  a copy this deployment has released. That is deliberate, and it is
 *  what lets a surface tell "there is no copy here" apart from "there
 *  is a copy here nobody can confirm", which is what the access and
 *  verification_class fields are for. Nothing here is a price, a bill
 *  or an estimate of how long a restore will take; see access. */
export interface WirePlacement {
  access: "immediate" | "requires_restore" | "restoring" | "unreachable";
  location: string;
  medium: string;
  medium_type: "local" | "s3";
  size_bytes?: number;
  status: "ACTIVE" | "DELETE_PENDING";
  storage_class?: string;
  verification_class?: "content" | "attested" | "existence";
  verified_at?: string;
}

/** The restore_placement action's own parameters. Present only when
 *  action is restore_placement, and refused when it is not: a body
 *  carrying restore parameters for a run_cycle is a request that has
 *  confused two operations, and answering it cheerfully is how the
 *  expensive version of the same mistake gets made later. */
export interface WireRestoreOperationRequest {
  acknowledged: boolean;
  artifact_id: string;
  medium: string;
  window_days: number;
}

/** One backup this plan would relocate, and both ends of the move
 *  (EPIC E, FR-27). A move is a statement about PLACEMENT and nothing
 *  else: planning one never adds a backup to the keep set and never
 *  removes one, which is why moves travel beside the verdicts rather
 *  than inside them. There is deliberately no field here for what a
 *  provider would charge to run this, how long a provider might take,
 *  or the key material that reaches either end, and there never will
 *  be: this product holds none of those three, so a field for one
 *  could only be filled with a guess. */
export interface WireRetentionMove {
  artifact: string;
  from_medium: string;
  to_medium: string;
}

/** One backup set's OWN retention policy, exactly as its
 *  configuration file carries it: unresolved, with every omitted
 *  field still omitted. An override names the WHOLE chain (a tiers
 *  list, or all three of daily_days, weekly_months and
 *  monthly_months) and half a chain is refused, because completing
 *  the missing half from the product defaults is how a set silently
 *  ends up retaining less than the operator who wrote the
 *  deployment's policy believes. Everything that is not the chain
 *  inherits from the deployment's resolved policy when omitted, so an
 *  override that names no timezone is reckoned in the deployment's,
 *  not in UTC. */
export interface WireRetentionOverride {
  acknowledge_medium_disclosure?: boolean;
  daily_days?: number;
  monthly_months?: number;
  protect_last_known_good?: boolean;
  tiers?: WireRetentionTier[];
  timezone?: string;
  week_starts_on?: string;
  weekly_months?: number;
}

/** A server-computed retention plan. The client may only apply one by
 *  id; it never proposes what to delete. */
export interface WireRetentionPlan {
  backup_set_id: string;
  config_revision: string;
  delete_count: number;
  expires_at: string;
  inventory_revision: string;
  keep_count: number;
  moves?: WireRetentionMove[];
  operation_id?: string;
  plan_id: string;
  reclaim_bytes: number;
  retention: WireRetentionSettings;
  retention_is_override: boolean;
  unconfirmed_placements?: string[];
  verdicts: WireRetentionVerdict[];
}

/** The closed value sets and bounds a retention chain is validated
 *  against, served rather than transcribed into a frontend. */
export interface WireRetentionSchema {
  default_tiers: WireRetentionTier[];
  granularities: string[];
  keep_max: number;
  period_days_max: number;
  reserved_tier_name: string;
  tier_name_pattern: string;
  window_units: string[];
}

/** The retention policy actually in effect. tiers is always the
 *  RESOLVED chain. */
export interface WireRetentionSettings {
  protect_last_known_good: boolean;
  tiers: WireRetentionTier[];
  timezone: string;
  week_starts_on: string;
}

/** One link in the retention chain, on the wire. The same shape is
 *  read and written, so a client round-trips exactly what it was
 *  served. That round trip is why every field a tier can carry is
 *  here: a chain write REPLACES the whole chain, so a field this
 *  shape omits is a field the save deletes from the operator's
 *  configuration file. */
export interface WireRetentionTier {
  granularity: string;
  keep: number;
  medium?: string;
  name: string;
  period_days?: number;
  window_unit?: string;
}

/** One tier's claim on an artifact, and which of the two placements
 *  made it. FR-18 places every artifact twice, once by the timestamp
 *  this manager discovered it and once by the producer's own
 *  timestamp on the remote object, and KEEP is the union. FR-8 treats
 *  the second as untrusted, so which pass selected a tier is a
 *  different fact with different consequences and travels with the
 *  tier rather than with the verdict: one artifact can be selected by
 *  DAILY through one placement and by MONTHLY through the other. */
export interface WireRetentionTierSelection {
  selected_by: "DISCOVERY" | "PRODUCER" | "BOTH" | "PROTECTION";
  tier: string;
}

/** What the plan decided for one artifact, and why. */
export interface WireRetentionVerdict {
  action: string;
  artifact: string;
  medium?: string;
  reason: string;
  tier_selections?: WireRetentionTierSelection[];
  tiers?: string[];
}

/** POST /backups/{source}/{set}/{name}/retry's optional body.
 *  Everything about the retry is decided by the backup's own recorded
 *  state, so there is nothing here that changes what happens: the
 *  note is recorded alongside the transition so a later failure of
 *  the same backup carries the context of what was tried last time,
 *  rather than only that something was. */
export interface WireRetryFailedRequest {
  note?: string;
}

/** POST /auth/password. Requires an already-authenticated session AND
 *  the current password: holding a cookie is not enough. */
export interface WireRotatePasswordRequest {
  currentPassword: string;
  newPassword: string;
}

/** What a run cycle is doing for one backup set right now (issue
 *  #350). It is the content of the warning shown before edit mode
 *  opens: discarding a partial transfer of a named artifact is a
 *  materially different cost from cancelling a scheduler tick that
 *  has not started work, and only a message saying which one it is
 *  lets an operator decide. */
export interface WireRunningWork {
  artifact: string;
  stage: string;
}

/** One key in this deployment's own key store. It carries no
 *  server-side path: SSHKeyRef.KeyFile is kept off the wire so a
 *  caller never learns this process's filesystem layout, and an
 *  inventory is not an exception to that. What travels instead is the
 *  id, the public half's algorithm and SHA256 fingerprint, the
 *  authorized_keys line, and which backup sets point at it. */
export interface WireSSHKey {
  algorithm: string;
  fingerprint: string;
  id: string;
  imported_at: string;
  passphrase_protected: boolean;
  problem?: string;
  public_key: string;
  used_by: string[];
}

/** One private key file this engine can actually see. Unlike SSHKey,
 *  this DOES carry a path, because a candidate's path is its identity
 *  to an operator and there is no other way to say which of several
 *  files is meant. What makes that safe is that the locations
 *  searched are a closed, constant set decided server-side, never
 *  caller-supplied and never walked recursively. The handle
 *  travelling back is the opaque id, never the path. */
export interface WireSSHKeyCandidate {
  algorithm: string;
  fingerprint: string;
  id: string;
  in_store: boolean;
  in_store_id?: string;
  location: string;
  mode: string;
  path: string;
  public_key: string;
  reason?: string;
  selectable: boolean;
}

/** One place the scan looked, reported whether or not anything was
 *  found there. Every location is always reported, including the
 *  absent ones: an empty candidate list has two readings, "you have
 *  no keys" and "I could not look where your keys are", and on a
 *  packaged install the engine is a distroless container with five
 *  mounts and no home directory, so the second is the true one. */
export interface WireSSHKeyDiscoveryLocation {
  found: number;
  kind: string;
  path: string;
  problem?: string;
}

/** GET /auth/session. */
export interface WireSessionResponse {
  username: string;
}

/** POST /backup-sets/{source}/{set}/enabled. A disabled backup set is
 *  excluded from every run cycle and nothing already backed up is
 *  touched, which is why this is state-changing but not destructive. */
export interface WireSetEnabledRequest {
  enabled: boolean;
}

/** POST /backup-sets/{source}/{set}/read-only. Declares, or
 *  withdraws, a backup set's read-only status (issue #282). Turning
 *  it on only prevents a future deletion; turning it back off does
 *  not retroactively authorise deleting anything already retained
 *  under it, so this is state-changing but not destructive. */
export interface WireSetReadOnlyRequest {
  read_only: boolean;
}

/** GET and PATCH /settings both return this: the settings now in
 *  effect plus the rules they were validated against. */
export interface WireSettingsResponse {
  capacity: WireCapacitySettings;
  mediums: WireStorageMediumSummary[];
  retention: WireRetentionSettings;
  schema: WireSettingsSchema;
}

/** The schema half of the settings response. */
export interface WireSettingsSchema {
  retention: WireRetentionSchema;
  storage: WireStorageSchema;
}

/** Where one storage medium's credentials come from. Exactly one of
 *  the four must be set, and none of them is credential MATERIAL:
 *  this is a reference in all four spellings. credentials_id is the
 *  one a browser uses, because it is the only one that names nothing
 *  about the manager's host. */
export interface WireStorageMediumCredentialsReference {
  command?: string[];
  credentials_id?: string;
  env?: string;
  file?: string;
}

/** One storage destination as a caller describes it: for POST
 *  /storage-mediums (declare it), PUT /storage-mediums/{id} (replace
 *  its description) and POST /storage-mediums/preflight (prove it
 *  before either). The same shape for all three deliberately, so what
 *  is proven and what is saved cannot be different destinations.
 *  There is no field here for credential material, and there never
 *  will be (FR-33): the credentials block names a reference. */
export interface WireStorageMediumRequest {
  bucket: string;
  credentials?: WireStorageMediumCredentialsReference;
  endpoint?: string;
  id: string;
  prefix?: string;
  region?: string;
  storage_class?: string;
  type: "s3";
  upload_verification?: "readback" | "attested";
}

/** One configured storage medium, as the settings surface reports it:
 *  what it is called, what kind of place it is, which bucket and
 *  region, and which storage class artifacts are written with. There
 *  is deliberately no field here for key material of any kind, and
 *  there never will be (FR-33). A credential reaches this product
 *  only as a reference to a file, an environment variable or a
 *  command, and none of those three has a spelling on this boundary
 *  at all. That absence now covers the WRITE direction too (POST/PUT
 *  below), and it extends to the credential's KIND: there is no field
 *  saying whether a medium reads a file, a variable or a command,
 *  because where a credential comes from is a fact about the
 *  manager's host that an API caller has no use for. An edit
 *  therefore does not have to resupply the credential; omitting it
 *  keeps the one already configured. */
export interface WireStorageMediumSummary {
  bucket: string;
  endpoint?: string;
  id: string;
  prefix?: string;
  reads_require_restore: boolean;
  region?: string;
  storage_class: string;
  type: "s3";
  upload_verification: "readback" | "attested";
}

/** One backup set's copies on a storage medium. */
export interface WireStorageMediumUsageBySet {
  only_copy_here: number;
  placements: number;
  set: string;
}

/** What the journal says is currently on one storage medium, listed
 *  rather than only counted. It asks the medium nothing: this is what
 *  the deployment RECORDED, and whether the endpoint answers right
 *  now is the preflight's question, asked separately. A count with no
 *  list is not something an operator can act on, which is why the
 *  backup sets are here. */
export interface WireStorageMediumUsageResponse {
  backup_sets: WireStorageMediumUsageBySet[];
  medium: string;
  placements: number;
}

/** The closed value sets and the consent text a storage-medium
 *  mapping is written against, served rather than transcribed into a
 *  frontend. */
export interface WireStorageSchema {
  medium_disclosure: string;
  retrieval_disclosure: string;
  verification_classes: WireVerificationClassInfo[];
}

/** One backup set's capacity assessment. */
export interface WireStorageStatus {
  available: boolean;
  available_bytes: number;
  backup_set_id: string;
  critical_free_bytes: number;
  free_bytes: number;
  level: "" | "OK" | "WARNING" | "CRITICAL";
  local_path: string;
  total_bytes: number;
  unavailable_reason: "" | "not_created" | "unreadable" | "misconfigured";
  warning_free_bytes: number;
}

/** POST /operations. The idempotency key is a header, not a body
 *  field: it is a property of the retry, not of the operation. action
 *  selects which of the parameter objects below is read;
 *  restore_placement reads restore, run_backup_set reads
 *  backup_set_id, and run_cycle reads neither. */
export interface WireSubmitOperationRequest {
  action: string;
  backup_set_id?: string;
  config_revision: string;
  restore?: WireRestoreOperationRequest;
}

/** POST /backup-sets/test-connection. A reachability and
 *  authentication check, in one of two modes: name backup_set_id to
 *  re-check a set that already exists, or supply the connection
 *  details to check a candidate before it is saved. Exactly one mode
 *  per request. A client testing a persisted set neither knows nor
 *  has to echo back that set's key reference and trusted host line,
 *  which is what keeps a read-only "does this still work" check from
 *  being able to test something else. */
export interface WireTestConnectionRequest {
  backup_set_id?: string;
  host?: string;
  known_hosts_line?: string;
  port?: number;
  remote_path?: string;
  ssh_key_id?: string;
  user?: string;
}

/** The outcome of a connection test, as a verdict and as the six
 *  steps that produced it. `ok` and `message` mean exactly what they
 *  have always meant, so a client reading only those keeps working;
 *  `checks` is what the test actually DID, one entry per step and
 *  always all of them, in the order they run. Both modes of this
 *  endpoint answer the same six steps: a caller no longer has to
 *  remember which request it sent to know what shape comes back. */
export interface WireTestConnectionResponse {
  checks?: WireConnectionCheck[];
  message?: string;
  ok: boolean;
}

/** ONE host key a backup set actually pins, named the way an operator
 *  compares it: the algorithm and the SHA256 fingerprint, the form
 *  `ssh-keygen -lf` prints and the wizard's verify step shows. Never
 *  the key material, which is a wall of base64 nobody checks by eye. */
export interface WireTrustedHostKey {
  algorithm: string;
  fingerprint: string;
}

/** PATCH /backup-sets/{source}/{set}. A SPARSE edit of one
 *  already-persisted backup set (issue #350): every property is
 *  optional, and a property this body omits is left exactly as it is
 *  rather than cleared. That is what lets the Web UI's per-box Save
 *  persist only the box it belongs to. It deliberately carries no
 *  name/source_name: a backup set's identity keys every journal row,
 *  artifact id and recovery manifest it has ever produced, so a
 *  rename is a migration rather than an edit. It does carry
 *  ssh_key_id and known_hosts_line (issue #572), because a key
 *  replaced on the source host and a host key that changes when a
 *  server is rebuilt are both ordinary events a set has to be able to
 *  be told about, and until they were here the only route was to
 *  remove the set and create it again. Both are still references
 *  produced by the import and probe steps rather than material typed
 *  here, and re-trusting a host is still a trust decision, which is
 *  what acknowledge_host_key_change is for. */
export interface WireUpdateBackupSetRequest {
  acknowledge_host_key_change?: boolean;
  acknowledge_repoint?: boolean;
  completion_strategy?: "rename" | "marker" | "stable";
  host?: string;
  include?: string[];
  known_hosts_line?: string;
  local_path?: string;
  port?: number;
  remote_path?: string;
  ssh_key_id?: string;
  stable_for_seconds?: number;
  stale_after_seconds?: number;
  user?: string;
  validator_id?: string;
}

/** A PARTIAL capacity update. An omitted field is left exactly as the
 *  running configuration has it. An explicit 0 is a request, not an
 *  omission: on this block zero means "no cap" and "no warning line",
 *  which is why every field is nullable rather than a plain number. */
export interface WireUpdateCapacitySettings {
  cap_bytes?: number;
  critical_free_bytes?: number;
  safety_margin_bytes?: number;
  warning_free_bytes?: number;
}

/** A PARTIAL retention update. An omitted field is left exactly as
 *  the running configuration has it; omitting tiers leaves the chain,
 *  and a legacy file's own spelling of it, untouched. */
export interface WireUpdateRetentionSettings {
  protect_last_known_good?: boolean;
  tiers?: WireRetentionTier[];
  timezone?: string;
  week_starts_on?: string;
}

/** PATCH /settings. An enumerated request type, never a configuration
 *  passthrough. */
export interface WireUpdateSettingsRequest {
  acknowledge_medium_disclosure?: boolean;
  capacity?: WireUpdateCapacitySettings;
  retention?: WireUpdateRetentionSettings;
}

/** One registered application validator. An id and a sentence, and
 *  deliberately nothing else: the script it resolves to is
 *  server-side and a client never learns it. */
export interface WireValidator {
  id: string;
  summary: string;
}

/** One rung of the verification ladder (FR-31), with what it proves
 *  and what achieving it takes, in the engine's own words. Served
 *  rather than transcribed into a frontend, for the reason the
 *  retention schema is served: a surface holding its own copy of what
 *  "existence" proves eventually says something the engine does not. */
export interface WireVerificationClassInfo {
  class: "content" | "attested" | "existence";
  downloads_object: boolean;
  proves: string;
  requires: string;
}

/** GET /system/version. Nothing here names an implementation: no
 *  rclone, no SQLite, no filesystem path. */
export interface WireVersionResponse {
  api_version: string;
  commit: string;
  config_revision: string;
  configured: boolean;
  core_version: string;
  deployment_id: string;
  engine_version: string;
  go_version: string;
  ready: boolean;
}

